{"explanation":"The controller preserves the initial data model, tracks only the latest loading request, and emits effects for cancellation and request issuance in order. Settlements are accepted only for the mounted, loading request whose ID matches current. Results persist across searches, failures, and cancellation as required. Disposal cancels any active request, resets data, and unmounts; only mount restores the initial mounted state.","program":"function solve({config,state,event}){
  const initial=()=>({mounted:true,query:"",current:null,loading:false,result:null,error:null});
  let s=state==null?initial():state;
  let effects=[];
  const output=()=>({mounted:s.mounted,query:s.query,current:s.current,loading:s.loading,result:s.result,error:s.error,effects});
  if(!s.mounted){
    if(event&&event.type==="mount")s=initial();
    return {state:s,output:output()};
  }
  if(!event||typeof event!=="object")return {state:s,output:output()};
  if(event.type==="search"){
    if(s.loading)effects.push({type:"cancel",id:s.current});
    s.current=event.id;
    s.query=event.query;
    s.loading=true;
    s.error=null;
    effects.push({type:"request",id:event.id,query:event.query});
  }else if(event.type==="success"){
    if(s.loading&&s.current===event.id){
      s.result=event.result;
      s.error=null;
      s.loading=false;
    }
  }else if(event.type==="failure"){
    if(s.loading&&s.current===event.id){
      s.error=event.error;
      s.loading=false;
    }
  }else if(event.type==="cancel"){
    if(s.loading)effects.push({type:"cancel",id:s.current});
    s.loading=false;
    s.current=null;
    s.error=null;
  }else if(event.type==="dispose"){
    if(s.loading)effects.push({type:"cancel",id:s.current});
    s=initial();
    s.mounted=false;
  }
  return {state:s,output:output()};
}"}
